1. //! Minimal derrick command-line interface for T008.
2. 
3. #![allow(clippy::print_stdout)]
4. #![allow(clippy::print_stderr)]
5. 
6. use std::ffi::OsString;
7. use std::path::{Path, PathBuf};
8. use std::process::ExitCode;
9. 
10. use clap::{CommandFactory, Parser};
11. use commands::{Cli, Command};
12. use thiserror::Error;
13. 
14. mod commands;
15. mod exit_code;
16. mod output;
17. mod telemetry;
18. 
19. /// Runs the CLI with an argument iterator and returns the process exit code.
20. pub async fn run<I, T>(args: I) -> ExitCode
21. where
22.     I: IntoIterator<Item = T>,
23.     T: Into<OsString> + Clone,
24. {
25.     let cli = match Cli::try_parse_from(args) {
26.         Ok(cli) => cli,
27.         Err(error) => {
28.             let code = error.exit_code();
29.             if let Err(print_error) = error.print() {
30.                 eprintln!("failed to print clap error: {print_error}");
31.             }
32.             return exit_code::from_i32(code);
33.         }
34.     };
35. 
