     #[arg(long)]
     pub(crate) batch: Option<String>,
 }

 #[derive(Debug, Args)]
 pub(crate) struct StackSubmitArgs {
     /// Only submit tickets in this batch.
     #[arg(long)]
     pub(crate) batch: Option<String>,
 }

 /// Arguments for `derrick switch`.
